src/modules/social/domain/expense.entity.source:
/**
 * `Expense` domain entity — splitwise-style group expense on a trip.
 *
 * DDD refactor by [F4]: the invariants below (amount shape + range,
 * currency shape, split-share sum + bounds, payer-must-participate)
 * USED TO live inline in `CreateExpenseUseCase.validate()` — the
 * "anemic data bag + use-case" anti-pattern the road-to-10 review
 * called out. They now live on the entity itself, behind:
 *
 *   - `Expense.create(input)` — single entry point for NEW expenses
 *     (returns the validated input ready for repo persistence; the
 *     DB assigns id + timestamps).
 *   - `Expense.fromPersistence(row)` — single entry point for
 *     reconstructing an Expense from a DB row (no validation; DB
 *     rows are by construction already valid).
 *
 * The use-case shrinks to: auth-check → `Expense.create()` →
 * `repo.create()` → invalidate cache.
 *
 * Money is carried as a string (Decimal's DB type is `numeric(10,2)`;
 * Prisma returns a Decimal we normalize to a 2-dp fixed string).
 * `splitShare` is a `{userId: number}` map summing to 1.0 ± 0.0001.
 *
 * Installed by prompt [IV.18.12.4]; entity-ized by [F4].
 */
import { ValidationError } from '@app/errors';

export type SplitShareMap = Readonly<Record<string, number>>;

/** Amount string the entity accepts (and the DB stores). Lets the
 *  unit tests + the use-case talk in the same currency. */
const AMOUNT_REGEX = /^\d+(\.\d{1,2})?$/;
const MAX_AMOUNT = 99_999_999.99;
const CURRENCY_REGEX = /^[A-Z]{3}$/;
const SHARE_SUM_TOLERANCE = 0.0001;

/** Input shape for `Expense.create()` — the new-expense payload BEFORE
 *  the DB assigns id + timestamps. */
export interface CreateExpenseInput {
  readonly tripId: string;
  readonly paidById: string;
  /** 2-dp fixed string ("12.50"). Entity validates shape + range. */
  readonly amountUsd: string;
  /** ISO 4217 code (3 letters). Entity uppercases as a courtesy. */
  readonly currency: string;
  readonly note: string | null;
  readonly splitShare: SplitShareMap;
}

/** Row shape coming back from the Prisma adapter — id + timestamps
 *  filled in. The repo passes this to `Expense.fromPersistence()`. */
export interface ExpensePersistenceRow {
  readonly id: string;
  readonly tripId: string;
  readonly paidById: string;
  readonly amountUsd: string;
  readonly currency: string;
  readonly note: string | null;
  readonly splitShare: SplitShareMap;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class Expense {
  // Public readonly fields — same shape as the old `interface
  // Expense`, so consumers reading `.tripId` / `.amountUsd` /
  // `.splitShare` don't change.
  readonly id: string;
  readonly tripId: string;
  readonly paidById: string;
  readonly amountUsd: string;
  readonly currency: string;
  readonly note: string | null;
  readonly splitShare: SplitShareMap;
  readonly createdAt: Date;
  readonly updatedAt: Date;

  private constructor(row: ExpensePersistenceRow) {
    this.id = row.id;
    this.tripId = row.tripId;
    this.paidById = row.paidById;
    this.amountUsd = row.amountUsd;
    this.currency = row.currency;
    this.note = row.note;
    this.splitShare = row.splitShare;
    this.createdAt = row.createdAt;
    this.updatedAt = row.updatedAt;
  }

  /**
   * Validate + return a normalized CreateExpenseInput ready for
   * `ExpenseRepository.create()`. Throws `ValidationError` on any
   * invariant break. Does NOT instantiate an `Expense` because the
   * DB assigns id + timestamps — the repo round-trips through
   * `Expense.fromPersistence()` with the row it just wrote.
   *
   * Centralises every invariant the use-case used to inline:
   *   I1 amount matches `^\d+(\.\d{1,2})?$`
   *   I2 amount > 0 and ≤ 99,999,999.99 (numeric(10,2) ceiling)
   *   I3 currency uppercases to 3 letters (ISO 4217 shape)
   *   I4 splitShare is non-empty
   *   I5 every share is a finite number in (0, 1]
   *   I6 shares sum to 1.0 ± 0.0001
   *   I7 payer appears in splitShare
   */
  static create(input: CreateExpenseInput): CreateExpenseInput {
    // I1
    if (!AMOUNT_REGEX.test(input.amountUsd)) {
      throw new ValidationError(
        'Amount must be a positive decimal with at most 2 dp',
        { amountUsd: ['format: <int>.<up to 2 dp>'] },
        { amountUsd: input.amountUsd },
        'INVALID_AMOUNT',
      );
    }
    // I2
    const num = Number(input.amountUsd);
    if (!Number.isFinite(num) || num <= 0 || num > MAX_AMOUNT) {
      throw new ValidationError(
        'Amount out of range',
        { amountUsd: [`must be in (0, ${MAX_AMOUNT}]`] },
        { amountUsd: input.amountUsd },
        'INVALID_AMOUNT',
      );
    }
    // I3 (uppercase first so the caller doesn't have to)
    const currency = input.currency.toUpperCase();
    if (!CURRENCY_REGEX.test(currency)) {
      throw new ValidationError(
        'Currency must be ISO 4217 (3 letters)',
        { currency: ['must be 3 uppercase letters'] },
        { currency: input.currency },
        'INVALID_CURRENCY',
      );
    }
    // I4
    const entries = Object.entries(input.splitShare);
    if (entries.length === 0) {
      throw new ValidationError(
        'splitShare must have at least one participant',
        { splitShare: ['must be non-empty'] },
        {},
        'INVALID_SPLIT',
      );
    }
    let sum = 0;
    for (const [userId, share] of entries) {
      // I5 (key + value)
      if (typeof userId !== 'string' || userId.length === 0) {
        throw new ValidationError(
          'splitShare keys must be non-empty strings',
          { splitShare: ['key malformed'] },
          {},
          'INVALID_SPLIT',
        );
      }
      if (typeof share !== 'number' || !Number.isFinite(share) || share <= 0 || share > 1) {
        throw new ValidationError(
          `splitShare[${userId}] must be in (0, 1]`,
          { splitShare: ['each share must be > 0 and ≤ 1'] },
          { userId, share },
          'INVALID_SPLIT',
        );
      }
      sum += share;
    }
    // I6
    if (Math.abs(sum - 1) > SHARE_SUM_TOLERANCE) {
      throw new ValidationError(
        `splitShare must sum to 1.0 (got ${sum.toFixed(4)})`,
        { splitShare: ['sum must equal 1.0'] },
        { sum },
        'INVALID_SPLIT',
      );
    }
    // I7
    if (input.splitShare[input.paidById] === undefined) {
      throw new ValidationError(
        'Payer must appear in splitShare',
        { splitShare: ['must include the payer'] },
        { payerId: input.paidById },
        'INVALID_SPLIT',
      );
    }
    return { ...input, currency };
  }

  /**
   * Wrap a persisted row in an `Expense` instance. The DB row is
   * by construction already valid (it satisfied the schema +
   * passed through `Expense.create()` on the way in), so no
   * validation runs here.
   */
  static fromPersistence(row: ExpensePersistenceRow): Expense {
    return new Expense(row);
  }
}

/**
 * Per-user net balance on a trip. Positive = owed TO this user
 * (they paid more than their share); negative = this user owes
 * the group. All balances for a trip sum to zero (modulo rounding).
 */
export interface UserBalance {
  readonly userId: string;
  readonly netUsd: string;
}

src/modules/account/domain/trusted-conta.source:
/**
 * V.UX.13 — pre-set safety contact. On SOS trigger the
 * NOTIFY_CONTACTS_PORT fans out a "your traveler triggered SOS at
 * <coords>" message to each row.
 *
 * DDD refactor by [G4.3]:
 *   C1 userId non-empty
 *   C2 name non-empty + ≤ TRUSTED_CONTACT_MAX_NAME_CHARS after trim
 *   C3 at least one of phone / email must be non-null after trim
 *     (the "channel required" rule that drives the SOS fan-out)
 *   C4 phone trimmed-to-null when blank, ≤ 32 chars
 *   C5 email trimmed-to-null when blank, ≤ 254 chars (RFC 5321)
 *     + contains a `@`
 *
 * The MAX_CONTACTS_PER_USER cap stays in the use-case because it
 * needs the repository to count siblings.
 *
 * Installed by prompt [V.UX.13]; entity-ized by [G4.3].
 */
import { ValidationError } from '@app/errors';

export const TRUSTED_CONTACT_MAX_NAME_CHARS = 120;
export const TRUSTED_CONTACT_MAX_PHONE_CHARS = 32;
export const TRUSTED_CONTACT_MAX_EMAIL_CHARS = 254;

/** Input shape for `TrustedContact.create()` — the new-contact
 *  payload BEFORE the DB assigns id + timestamps. */
export interface CreateTrustedContactInput {
  readonly userId: string;
  readonly name: string;
  readonly phone: string | null;
  readonly email: string | null;
}

/** Row shape returned by the Prisma adapter. */
export interface TrustedContactPersistenceRow {
  readonly id: string;
  readonly userId: string;
  readonly name: string;
  readonly phone: string | null;
  readonly email: string | null;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class TrustedContact {
  readonly id: string;
  readonly userId: string;
  readonly name: string;
  readonly phone: string | null;
  readonly email: string | null;
  readonly createdAt: Date;
  readonly updatedAt: Date;

  private constructor(row: TrustedContactPersistenceRow) {
    this.id = row.id;
    this.userId = row.userId;
    this.name = row.name;
    this.phone = row.phone;
    this.email = row.email;
    this.createdAt = row.createdAt;
    this.updatedAt = row.updatedAt;
  }

  /**
   * Validate + return a trimmed/coerced CreateTrustedContactInput
   * ready for `TrustedContactRepository.create()`. Throws
   * `ValidationError` on any invariant break.
   *
   *   C1 userId non-empty
   *   C2 name non-empty + ≤ TRUSTED_CONTACT_MAX_NAME_CHARS after trim
   *   C3 phone OR email non-null after trim (channel required)
   *   C4 phone (when set) ≤ TRUSTED_CONTACT_MAX_PHONE_CHARS
   *   C5 email (when set) ≤ TRUSTED_CONTACT_MAX_EMAIL_CHARS + contains @
   */
  static create(input: CreateTrustedContactInput): CreateTrustedContactInput {
    if (typeof input.userId !== 'string' || input.userId.length === 0) {
      throw new ValidationError(
        'userId must be a non-empty string',
        { userId: ['must be non-empty'] },
        {},
        'INVALID_TRUSTED_CONTACT',
      );
    }
    const name = input.name.trim();
    if (name.length === 0 || name.length > TRUSTED_CONTACT_MAX_NAME_CHARS) {
      throw new ValidationError(
        `name must be 1..${TRUSTED_CONTACT_MAX_NAME_CHARS} chars (after trim)`,
        { name: ['out of range'] },
        { length: name.length },
        'INVALID_TRUSTED_CONTACT',
      );
    }
    const phone = input.phone && input.phone.trim().length > 0 ? input.phone.trim() : null;
    const email = input.email && input.email.trim().length > 0 ? input.email.trim() : null;
    if (!phone && !email) {
      throw new ValidationError(
        'A trusted contact needs at least a phone or an email',
        { phone: ['or email is required'], email: ['or phone is required'] },
        {},
        'CONTACT_CHANNEL_REQUIRED',
      );
    }
    if (phone && phone.length > TRUSTED_CONTACT_MAX_PHONE_CHARS) {
      throw new ValidationError(
        `phone must be ≤ ${TRUSTED_CONTACT_MAX_PHONE_CHARS} chars`,
        { phone: ['too long'] },
        { length: phone.length },
        'INVALID_TRUSTED_CONTACT',
      );
    }
    if (email && (email.length > TRUSTED_CONTACT_MAX_EMAIL_CHARS || !email.includes('@'))) {
      throw new ValidationError(
        'email is malformed or too long',
        { email: ['invalid'] },
        { length: email.length },
        'INVALID_TRUSTED_CONTACT',
      );
    }
    return { userId: input.userId, name, phone, email };
  }

  /** Wrap a persisted row in a `TrustedContact` instance. */
  static fromPersistence(row: TrustedContactPersistenceRow): TrustedContact {
    return new TrustedContact(row);
  }
}

src/modules/diary/domain/diary-entry.ent.source:
/**
 * `DiaryEntry` domain entity — Adventure Diary. No Nest/Prisma
 * imports (clean/hex: domain has zero outward deps).
 *
 * DDD refactor by [G4.4]: 4 invariants moved off
 * `CreateDiaryEntryUseCase`:
 *   D1 title 1..DIARY_MAX_TITLE chars (after trim)
 *   D2 body 1..DIARY_MAX_BODY chars (after trim)
 *   D3 mood ≤ DIARY_MAX_MOOD chars (after trim, or null)
 *   D4 entryDate parses to a valid Date
 *
 * The gamification award rule (`applyEntry`) stays in `gamification.ts`
 * (separate pure domain function with its own snapshot input shape).
 *
 * Installed for the adventure-diary feature; entity-ized by [G4.4].
 */
import { ValidationError } from '@app/errors';

export const DIARY_MAX_TITLE = 200;
export const DIARY_MAX_BODY = 20_000;
export const DIARY_MAX_MOOD = 40;

/** Input shape for `DiaryEntry.create()` — string `entryDate` because
 *  the controller hands us an ISO string; the factory parses it. */
export interface CreateDiaryEntryInput {
  readonly userId: string;
  readonly tripId?: string | null;
  readonly title: string;
  readonly body: string;
  readonly mood?: string | null;
  readonly aiAssisted?: boolean;
  /** ISO date string (date-only ok). Optional — defaults to now. */
  readonly entryDate?: string;
}

/** Trimmed/coerced shape returned by `create()`, ready for repo. */
export interface NormalisedDiaryEntry {
  readonly userId: string;
  readonly tripId: string | null;
  readonly title: string;
  readonly body: string;
  readonly mood: string | null;
  readonly aiAssisted: boolean;
  readonly entryDate: Date;
}

/** Row shape returned by the Prisma adapter. */
export interface DiaryEntryPersistenceRow {
  readonly id: string;
  readonly userId: string;
  readonly tripId: string | null;
  readonly title: string;
  readonly body: string;
  readonly mood: string | null;
  readonly aiAssisted: boolean;
  readonly entryDate: Date;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class DiaryEntry {
  readonly id: string;
  readonly userId: string;
  readonly tripId: string | null;
  readonly title: string;
  readonly body: string;
  readonly mood: string | null;
  readonly aiAssisted: boolean;
  /** Date-only semantics — the adventure day this entry is about. */
  readonly entryDate: Date;
  readonly createdAt: Date;
  readonly updatedAt: Date;

  private constructor(row: DiaryEntryPersistenceRow) {
    this.id = row.id;
    this.userId = row.userId;
    this.tripId = row.tripId;
    this.title = row.title;
    this.body = row.body;
    this.mood = row.mood;
    this.aiAssisted = row.aiAssisted;
    this.entryDate = row.entryDate;
    this.createdAt = row.createdAt;
    this.updatedAt = row.updatedAt;
  }

  /**
   * Validate + return a normalised payload ready for
   * `DiaryRepository.create()`. Throws `ValidationError` on D1-D4.
   *
   *   D1 title 1..DIARY_MAX_TITLE chars (after trim)
   *   D2 body 1..DIARY_MAX_BODY chars (after trim)
   *   D3 mood ≤ DIARY_MAX_MOOD chars (after trim) — empty becomes null
   *   D4 entryDate parses to a valid Date (or defaults to now)
   */
  static create(input: CreateDiaryEntryInput): NormalisedDiaryEntry {
    const title = input.title.trim();
    if (title.length === 0 || title.length > DIARY_MAX_TITLE) {
      throw new ValidationError(
        `Title must be 1–${DIARY_MAX_TITLE} characters`,
        { title: [`1–${DIARY_MAX_TITLE} characters`] },
        { length: title.length },
        'INVALID_DIARY_TITLE',
      );
    }
    const body = input.body.trim();
    if (body.length === 0 || body.length > DIARY_MAX_BODY) {
      throw new ValidationError(
        `Body must be 1–${DIARY_MAX_BODY} characters`,
        { body: [`1–${DIARY_MAX_BODY} characters`] },
        { length: body.length },
        'INVALID_DIARY_BODY',
      );
    }
    const mood = input.mood?.trim() || null;
    if (mood && mood.length > DIARY_MAX_MOOD) {
      throw new ValidationError(
        'Mood too long',
        { mood: [`at most ${DIARY_MAX_MOOD} characters`] },
        { length: mood.length },
        'INVALID_DIARY_MOOD',
      );
    }
    const entryDate = input.entryDate ? new Date(input.entryDate) : new Date();
    if (Number.isNaN(entryDate.getTime())) {
      throw new ValidationError(
        'entryDate is not a valid date',
        { entryDate: ['must be an ISO date'] },
        { entryDate: input.entryDate },
        'INVALID_DIARY_DATE',
      );
    }
    return {
      userId: input.userId,
      tripId: input.tripId ?? null,
      title,
      body,
      mood,
      aiAssisted: input.aiAssisted === true,
      entryDate,
    };
  }

  /** Wrap a persisted row in a `DiaryEntry` instance. */
  static fromPersistence(row: DiaryEntryPersistenceRow): DiaryEntry {
    return new DiaryEntry(row);
  }
}

/** Back-compat alias — the prior `NewDiaryEntry` interface mirrored
 *  the repo's `create()` input. After [G4.4] the canonical shape is
 *  `NormalisedDiaryEntry` (entity output), but the repo port still
 *  imports `NewDiaryEntry` so we keep the name as a synonym. */
export type NewDiaryEntry = NormalisedDiaryEntry;

src/modules/media/domain/media-asset.ent.source:
/**
 * `MediaAsset` domain entity. v1 tracks just the fields needed for
 * presigned-upload flow: ownership, kind, lifecycle status, the raw
 * S3 key, and (since `[IV.18.12.14]`) the EXIF-stripped flag that
 * gates location-derived features. `variants` (POST.5) /
 * `coordinates` / `takenAt` land in later slices when the media
 * service transcodes + strips EXIF out-of-band.
 *
 * `exifStripped`: confirm-upload sets this to `true` for
 * `kind: 'image'` as a stub — real strip-then-reupload happens
 * out-of-band in `media-service`. Until then any feature that
 * derives location/EXIF from the raw bytes MUST gate on this
 * flag and refuse to surface raw EXIF to other users.
 *
 * DDD refactor by [G4.3]:
 *   M1 ownerId + s3KeyRaw non-empty
 *   M2 kind ∈ {image, video}
 *   M3 caption (when set) ≤ MEDIA_MAX_CAPTION_CHARS after trim
 *   + `assertCanMarkReady(asset)` for the status state machine
 *     (`processing` → `ready` only; `ready`/`failed` terminal)
 *   + `normaliseCaption(input)` — the V.UX.11 trim+slice utility
 *
 * Installed by prompt [IV.18.12.1]; entity-ized by [G4.3].
 */
import { ConflictError, ValidationError } from '@app/errors';

export type MediaKind = 'image' | 'video';
export const MEDIA_KINDS: readonly MediaKind[] = ['image', 'video'];

export type MediaStatus = 'processing' | 'ready' | 'failed';
export const MEDIA_STATUSES: readonly MediaStatus[] = ['processing', 'ready', 'failed'];

export const MEDIA_MAX_CAPTION_CHARS = 280;

/** POST.5 — one entry in `MediaAsset.variants` for an image's
 *  Sharp-generated alternates (thumb / medium WebP). */
export interface MediaAssetVariant {
  readonly label: string;
  readonly format: string;
  readonly s3Key: string;
  readonly width: number;
  readonly height: number;
  readonly bytes: number;
  readonly sha256: string;
}

/** Input shape for `MediaAsset.create()` — the new-asset payload
 *  BEFORE the DB assigns id + timestamps. Status defaults to
 *  `processing`; the caller doesn't choose it. */
export interface CreateMediaAssetInput {
  readonly ownerId: string;
  readonly tripId: string | null;
  readonly kind: MediaKind;
  readonly s3KeyRaw: string;
}

/** Row shape returned by the Prisma adapter. */
export interface MediaAssetPersistenceRow {
  readonly id: string;
  readonly ownerId: string;
  readonly tripId: string | null;
  readonly memoryBookId: string | null;
  readonly kind: MediaKind;
  readonly status: MediaStatus;
  readonly s3KeyRaw: string;
  readonly exifStripped: boolean;
  readonly caption: string | null;
  readonly position: number;
  readonly variants: readonly MediaAssetVariant[] | null;
  readonly createdAt: Date;
}

export class MediaAsset {
  readonly id: string;
  readonly ownerId: string;
  readonly tripId: string | null;
  readonly memoryBookId: string | null;
  readonly kind: MediaKind;
  readonly status: MediaStatus;
  readonly s3KeyRaw: string;
  readonly exifStripped: boolean;
  /** V.UX.11 — per-asset narrative for memory-book story mode. */
  readonly caption: string | null;
  /** V.UX.11 — sort order within the memory book (0-based). */
  readonly position: number;
  /** POST.5 — Sharp-generated alternates; `null` when the pipeline
   *  has not run (legacy rows, videos, or a fresh image still in
   *  the pipeline). */
  readonly variants: readonly MediaAssetVariant[] | null;
  readonly createdAt: Date;

  private constructor(row: MediaAssetPersistenceRow) {
    this.id = row.id;
    this.ownerId = row.ownerId;
    this.tripId = row.tripId;
    this.memoryBookId = row.memoryBookId;
    this.kind = row.kind;
    this.status = row.status;
    this.s3KeyRaw = row.s3KeyRaw;
    this.exifStripped = row.exifStripped;
    this.caption = row.caption;
    this.position = row.position;
    this.variants = row.variants;
    this.createdAt = row.createdAt;
  }

  /** Validate + return a normalised CreateMediaAssetInput ready for
   *  `MediaAssetRepository.create()`. */
  static create(input: CreateMediaAssetInput): CreateMediaAssetInput {
    if (typeof input.ownerId !== 'string' || input.ownerId.length === 0) {
      throw new ValidationError(
        'ownerId must be a non-empty string',
        { ownerId: ['must be non-empty'] },
        {},
        'INVALID_MEDIA_ASSET',
      );
    }
    if (typeof input.s3KeyRaw !== 'string' || input.s3KeyRaw.length === 0) {
      throw new ValidationError(
        's3KeyRaw must be a non-empty string',
        { s3KeyRaw: ['must be non-empty'] },
        {},
        'INVALID_MEDIA_ASSET',
      );
    }
    if (!MEDIA_KINDS.includes(input.kind)) {
      throw new ValidationError(
        `kind must be one of ${MEDIA_KINDS.join(' | ')}`,
        { kind: [`unknown: ${input.kind}`] },
        { kind: input.kind },
        'INVALID_MEDIA_ASSET',
      );
    }
    return input;
  }

  /** V.UX.11 caption normalisation. Empty / whitespace input clears
   *  the field (returns null). Non-empty input is trimmed and capped
   *  at MEDIA_MAX_CAPTION_CHARS (cap by slice, not throw, to keep the
   *  UX forgiving — a 281-char caption shouldn't reject the save). */
  static normaliseCaption(input: string | null | undefined): string | null {
    if (input === null || input === undefined) return null;
    const trimmed = input.trim();
    if (trimmed.length === 0) return null;
    return trimmed.slice(0, MEDIA_MAX_CAPTION_CHARS);
  }

  /** Status state machine — `processing` is the only legal source for
   *  `markReady`. Throws `ConflictError(MEDIA_STATUS_LOCKED)` for any
   *  other current status so the repo can't silently flip a `failed`
   *  row back to `ready`. */
  static assertCanMarkReady(asset: MediaAsset): void {
    if (asset.status !== 'processing') {
      throw new ConflictError(
        `Media asset cannot transition to ready from status "${asset.status}"`,
        { mediaId: asset.id, currentStatus: asset.status },
        'MEDIA_STATUS_LOCKED',
      );
    }
  }

  /** Wrap a persisted row in a `MediaAsset` instance. */
  static fromPersistence(row: MediaAssetPersistenceRow): MediaAsset {
    return new MediaAsset(row);
  }
}

src/modules/safety/domain/agent-profile..source:
/**
 * V.UX.24 — agent / local-guide caller-self surfaces.
 *
 * Splits intentionally:
 *   - `AgentProfile` is the editable row the agent owns (bio,
 *     languages, regions, displayName) plus the read-only KYC
 *     status + rating aggregates.
 *   - `AgentBookingSummary` is the dashboard's compact booking
 *     row — full EscrowHold has more fields than the agent UI
 *     needs.
 *   - `AgentEarningsSummary` collapses the booking list into a
 *     dashboard total + count.
 *   - `AgentReviewWithResponse` mirrors the existing Review row
 *     plus the V.UX.24 `responseBody` / `responseAt` reply.
 *
 * DDD refactor by [G4.2]: 4 update invariants moved off
 * `UpdateAgentProfileUseCase`:
 *   A1 displayName 1..AGENT_MAX_DISPLAY_CHARS chars (after trim)
 *   A2 bio ≤ AGENT_MAX_BIO_CHARS chars
 *   A3 languages ≤ AGENT_MAX_LIST entries, each 2..AGENT_MAX_ENTRY_CHARS chars
 *   A4 regions  ≤ AGENT_MAX_LIST entries, each 2..AGENT_MAX_ENTRY_CHARS chars
 *
 * There's no `static create()` — rows are seeded / admin-created, not
 * minted by a public use-case. `static validateUpdate(input)` handles
 * the partial-update flow + trims/coerces each present field;
 * `static fromPersistence(row)` wraps Prisma rows.
 *
 * Installed by prompt [V.UX.24]; entity-ized by [G4.2].
 */
import { ValidationError } from '@app/errors';

export type AgentKycStatus = 'pending' | 'verified' | 'rejected';
export const AGENT_KYC_STATUSES: readonly AgentKycStatus[] = ['pending', 'verified', 'rejected'];

export const AGENT_MAX_DISPLAY_CHARS = 120;
export const AGENT_MAX_BIO_CHARS = 2000;
export const AGENT_MAX_LIST = 20;
export const AGENT_MIN_ENTRY_CHARS = 2;
export const AGENT_MAX_ENTRY_CHARS = 40;

/** Update payload — every field optional; presence means "the caller
 *  wants to change this." Pass through `AgentProfile.validateUpdate()`
 *  to get a trimmed/coerced shape ready for the repo. */
export interface AgentProfileUpdateInput {
  readonly displayName?: string;
  readonly bio?: string | null;
  readonly languages?: readonly string[];
  readonly regions?: readonly string[];
}

/** Trimmed/coerced shape returned by `validateUpdate()`. */
export interface AgentProfileUpdatePatch {
  readonly displayName?: string;
  readonly bio?: string | null;
  readonly languages?: readonly string[];
  readonly regions?: readonly string[];
}

/** Row shape returned by the Prisma adapter. */
export interface AgentProfilePersistenceRow {
  readonly id: string;
  readonly userId: string;
  readonly displayName: string;
  readonly bio: string | null;
  readonly kycStatus: AgentKycStatus;
  readonly verifiedAt: Date | null;
  readonly languages: readonly string[];
  readonly regions: readonly string[];
  readonly ratingAverage: number;
  readonly ratingCount: number;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class AgentProfile {
  readonly id: string;
  readonly userId: string;
  readonly displayName: string;
  readonly bio: string | null;
  readonly kycStatus: AgentKycStatus;
  readonly verifiedAt: Date | null;
  readonly languages: readonly string[];
  readonly regions: readonly string[];
  readonly ratingAverage: number;
  readonly ratingCount: number;
  readonly createdAt: Date;
  readonly updatedAt: Date;

  private constructor(row: AgentProfilePersistenceRow) {
    this.id = row.id;
    this.userId = row.userId;
    this.displayName = row.displayName;
    this.bio = row.bio;
    this.kycStatus = row.kycStatus;
    this.verifiedAt = row.verifiedAt;
    this.languages = row.languages;
    this.regions = row.regions;
    this.ratingAverage = row.ratingAverage;
    this.ratingCount = row.ratingCount;
    this.createdAt = row.createdAt;
    this.updatedAt = row.updatedAt;
  }

  /**
   * Validate a partial-update payload + return the trimmed/coerced
   * patch. Only the fields the caller actually passed are present in
   * the output — `undefined` stays `undefined`, `null` (for `bio`)
   * stays `null` (clear).
   *
   *   A1 displayName 1..AGENT_MAX_DISPLAY_CHARS chars (after trim)
   *   A2 bio ≤ AGENT_MAX_BIO_CHARS chars
   *   A3/A4 languages/regions ≤ AGENT_MAX_LIST entries, each
   *         AGENT_MIN_ENTRY_CHARS..AGENT_MAX_ENTRY_CHARS chars
   */
  static validateUpdate(input: AgentProfileUpdateInput): AgentProfileUpdatePatch {
    const patch: {
      -readonly [K in keyof AgentProfileUpdatePatch]: AgentProfileUpdatePatch[K];
    } = {};

    if (input.displayName !== undefined) {
      const trimmed = input.displayName.trim();
      if (trimmed.length === 0 || trimmed.length > AGENT_MAX_DISPLAY_CHARS) {
        throw new ValidationError(
          `displayName must be 1..${AGENT_MAX_DISPLAY_CHARS} chars`,
          { displayName: ['out of range'] },
          { length: trimmed.length },
          'INVALID_AGENT_DISPLAY_NAME',
        );
      }
      patch.displayName = trimmed;
    }

    if (input.bio !== undefined) {
      if (input.bio === null) {
        patch.bio = null;
      } else {
        const trimmed = input.bio.trim();
        if (trimmed.length > AGENT_MAX_BIO_CHARS) {
          throw new ValidationError(
            `bio must be ≤ ${AGENT_MAX_BIO_CHARS} chars`,
            { bio: ['too long'] },
            { length: trimmed.length },
            'INVALID_AGENT_BIO',
          );
        }
        patch.bio = trimmed;
      }
    }

    for (const field of ['languages', 'regions'] as const) {
      const list = input[field];
      if (list === undefined) continue;
      if (list.length > AGENT_MAX_LIST) {
        throw new ValidationError(
          `${field} must have ≤ ${AGENT_MAX_LIST} entries`,
          { [field]: ['too many'] },
          { count: list.length },
          'INVALID_AGENT_LIST',
        );
      }
      const trimmed: string[] = [];
      for (const entry of list) {
        const t = entry.trim();
        if (t.length < AGENT_MIN_ENTRY_CHARS || t.length > AGENT_MAX_ENTRY_CHARS) {
          throw new ValidationError(
            `each ${field} entry must be ${AGENT_MIN_ENTRY_CHARS}..${AGENT_MAX_ENTRY_CHARS} chars`,
            { [field]: ['entry out of range'] },
            { entry, length: t.length },
            'INVALID_AGENT_LIST',
          );
        }
        trimmed.push(t);
      }
      patch[field] = trimmed;
    }

    return patch;
  }

  /** Wrap a persisted row in an `AgentProfile` instance. */
  static fromPersistence(row: AgentProfilePersistenceRow): AgentProfile {
    return new AgentProfile(row);
  }
}

export type AgentEscrowState = 'held' | 'released' | 'refunded' | 'disputed';

export interface AgentBookingSummary {
  readonly id: string;
  readonly userId: string;
  readonly amountUsd: string; // Prisma Decimal → 2-decimal string.
  readonly currency: string;
  readonly state: AgentEscrowState;
  readonly heldAt: Date;
  readonly releasedAt: Date | null;
  readonly refundedAt: Date | null;
}

export interface AgentEarningsSummary {
  readonly grossUsd: string; // 2-decimal string.
  readonly bookingsCount: number;
}

export interface AgentReviewWithResponse {
  readonly id: string;
  readonly authorId: string;
  readonly rating: number;
  readonly body: string;
  readonly language: string;
  readonly verifiedBooking: boolean;
  readonly responseBody: string | null;
  readonly responseAt: Date | null;
  readonly createdAt: Date;
}

