/**
 * `SosEvent` domain entity. Mirrors the Prisma row minus the PostGIS
 * `coordinates` column. `trigger` is a free-form string so new
 * trigger modes (`fall_detected`, `geofence_exit`, `manual_tap`,
 * `voice_command`) don't need a schema migration.
 *
 * `resolvedAt` is null on create; flipping it (with an optional
 * note) is a separate write path. An unresolved event is "active"
 * — the UI/dashboard filters on that.
 *
 * DDD refactor by [G4.2]: 2 invariants moved off `TriggerSosUseCase`:
 *   O1 userId non-empty
 *   O2 trigger non-empty + ≤ 60 chars (after trim)
 *
 * lat/lng range checks stay in the use-case — they're a geo concern
 * and the entity intentionally has no coordinates field.
 *
 * Installed by prompt [IV.18.11.2]; entity-ized by [G4.2].
 */
import { ValidationError } from '@app/errors';

export const SOS_MAX_TRIGGER_LENGTH = 60;
export const SOS_MAX_RESOLUTION_NOTE_LENGTH = 2000;

/** Input shape for `SosEvent.create()` — payload to pass to
 *  `SosEventRepository.create()` (lat/lng added at the use-case
 *  boundary). */
export interface CreateSosEventInput {
  readonly userId: string;
  readonly trigger: string;
}

/** Row shape returned by the Prisma adapter. */
export interface SosEventPersistenceRow {
  readonly id: string;
  readonly userId: string;
  readonly trigger: string;
  readonly resolvedAt: Date | null;
  readonly resolutionNote: string | null;
  readonly createdAt: Date;
}

export class SosEvent {
  readonly id: string;
  readonly userId: string;
  readonly trigger: string;
  readonly resolvedAt: Date | null;
  readonly resolutionNote: string | null;
  readonly createdAt: Date;

  private constructor(row: SosEventPersistenceRow) {
    this.id = row.id;
    this.userId = row.userId;
    this.trigger = row.trigger;
    this.resolvedAt = row.resolvedAt;
    this.resolutionNote = row.resolutionNote;
    this.createdAt = row.createdAt;
  }

  /**
   * Validate + return a normalised CreateSosEventInput ready for
   * `SosEventRepository.create()`. Throws `ValidationError` on any
   * invariant break.
   */
  static create(input: CreateSosEventInput): CreateSosEventInput {
    if (typeof input.userId !== 'string' || input.userId.length === 0) {
      throw new ValidationError(
        'userId must be a non-empty string',
        { userId: ['must be non-empty'] },
        {},
        'INVALID_SOS_EVENT',
      );
    }
    const trigger = input.trigger.trim();
    if (trigger.length === 0 || trigger.length > SOS_MAX_TRIGGER_LENGTH) {
      throw new ValidationError(
        `trigger must be 1..${SOS_MAX_TRIGGER_LENGTH} chars (after trim)`,
        { trigger: ['out of range'] },
        { length: trigger.length },
        'INVALID_SOS_EVENT',
      );
    }
    return { userId: input.userId, trigger };
  }

  /** Validate the resolution note used when an admin/owner resolves
   *  an SOS event. Empty/whitespace → null (caller can store null). */
  static normaliseResolutionNote(note: string | null | undefined): string | null {
    if (note === null || note === undefined) return null;
    const trimmed = note.trim();
    if (trimmed.length === 0) return null;
    if (trimmed.length > SOS_MAX_RESOLUTION_NOTE_LENGTH) {
      throw new ValidationError(
        `resolutionNote must be ≤ ${SOS_MAX_RESOLUTION_NOTE_LENGTH} chars`,
        { resolutionNote: ['too long'] },
        { length: trimmed.length },
        'INVALID_SOS_EVENT',
      );
    }
    return trimmed;
  }

  /** Wrap a persisted row in a `SosEvent` instance. */
  static fromPersistence(row: SosEventPersistenceRow): SosEvent {
    return new SosEvent(row);
  }
}

src/modules/social/domain/review.entity..source:
/**
 * `Review` domain entity. Standalone OR trip-attached review of a
 * place / stay / eatery / agent.
 *
 * DDD refactor by [G4.1]: the 3 invariants that used to live inline
 * in `CreateReviewUseCase.validate()` (R1 rating-1..5-int,
 * R2 body-non-empty-≤5000-chars-after-trim, R3 language-ISO-639-1)
 * have moved onto the entity itself behind `Review.create(input)`.
 * The use-case becomes: gate (trip access + block) → `Review.create()`
 * → `repo.create()`.
 *
 * Persistence reconstruction goes through `Review.fromPersistence()` —
 * the repo adapter wraps Prisma rows in this static so the toDomain()
 * cast surface lives on the entity, not in infra.
 *
 * `tripId` is optional — reviews can be standalone (write a
 * review of a place you visited solo, no trip needed) or
 * trip-attached (so the trip's collaborators can read + the
 * author's "I went here on my Paris trip" context shows up).
 *
 * `targetType` is an enum: place | stay | eatery | agent.
 *
 * Unlike Vote (unique per user+target), Review has NO unique
 * constraint — a user can leave multiple reviews on the same
 * target from different trips over time.
 *
 * Installed by prompt [IV.18.12.5]; entity-ized by [G4.1].
 */
import { ValidationError } from '@app/errors';

export type ReviewTargetType = 'place' | 'stay' | 'eatery' | 'agent';

/** Validation rule limits (also the values asserted by the unit
 *  test). Exported so the use-case error messages can quote them
 *  without duplicating magic numbers. */
export const REVIEW_MIN_RATING = 1;
export const REVIEW_MAX_RATING = 5;
export const REVIEW_MAX_BODY_LENGTH = 5000;
const LANGUAGE_REGEX = /^[a-z]{2}$/;

/** Input shape for `Review.create()` — the new-review payload BEFORE
 *  the DB assigns id + timestamps. Mirrors `CreateReviewInput` on the
 *  port (kept in lockstep). */
export interface CreateReviewInput {
  readonly authorId: string;
  readonly tripId: string | null;
  readonly targetType: ReviewTargetType;
  readonly targetId: string;
  readonly rating: number;
  readonly body: string;
  readonly language: string;
}

/** Row shape returned by the Prisma adapter — id, timestamps, and the
 *  optional V.UX.24 response columns all filled in by the DB. */
export interface ReviewPersistenceRow {
  readonly id: string;
  readonly authorId: string;
  readonly tripId: string | null;
  readonly targetType: ReviewTargetType;
  readonly targetId: string;
  readonly rating: number;
  readonly body: string;
  readonly language: string;
  readonly verifiedBooking: boolean;
  readonly responseBody: string | null;
  readonly responseAt: Date | null;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class Review {
  readonly id: string;
  readonly authorId: string;
  readonly tripId: string | null;
  readonly targetType: ReviewTargetType;
  readonly targetId: string;
  readonly rating: number;
  readonly body: string;
  readonly language: string;
  readonly verifiedBooking: boolean;
  /**
   * V.UX.24 — target-owner reply (e.g. an agent replying to a
   * review about themselves). Stamped at most once; the use-case
   * rejects re-submissions. Null until the owner responds.
   */
  readonly responseBody: string | null;
  readonly responseAt: Date | null;
  readonly createdAt: Date;
  readonly updatedAt: Date;

  private constructor(row: ReviewPersistenceRow) {
    this.id = row.id;
    this.authorId = row.authorId;
    this.tripId = row.tripId;
    this.targetType = row.targetType;
    this.targetId = row.targetId;
    this.rating = row.rating;
    this.body = row.body;
    this.language = row.language;
    this.verifiedBooking = row.verifiedBooking;
    this.responseBody = row.responseBody;
    this.responseAt = row.responseAt;
    this.createdAt = row.createdAt;
    this.updatedAt = row.updatedAt;
  }

  /**
   * Validate + return a normalized CreateReviewInput ready for
   * `ReviewRepository.create()`. Throws `ValidationError` on any
   * invariant break.
   *
   *   R1 rating is an integer in [1, 5]
   *   R2 body is non-empty + ≤ 5000 chars (after trim)
   *   R3 language is exactly 2 lowercase ISO-639-1 letters
   *
   * Normalises: body.trim(), language.toLowerCase().
   */
  static create(input: CreateReviewInput): CreateReviewInput {
    if (
      !Number.isInteger(input.rating) ||
      input.rating < REVIEW_MIN_RATING ||
      input.rating > REVIEW_MAX_RATING
    ) {
      throw new ValidationError(
        `Rating must be an integer between ${REVIEW_MIN_RATING} and ${REVIEW_MAX_RATING}`,
        { rating: [`must be integer in [${REVIEW_MIN_RATING}, ${REVIEW_MAX_RATING}]`] },
        { rating: input.rating },
        'INVALID_RATING',
      );
    }
    const body = input.body.trim();
    if (body.length === 0) {
      throw new ValidationError(
        'Review body cannot be empty',
        { body: ['must be non-empty'] },
        {},
        'INVALID_REVIEW_BODY',
      );
    }
    if (body.length > REVIEW_MAX_BODY_LENGTH) {
      throw new ValidationError(
        'Review body too long',
        { body: [`must be ≤ ${REVIEW_MAX_BODY_LENGTH} chars (got ${body.length})`] },
        { length: body.length },
        'INVALID_REVIEW_BODY',
      );
    }
    const language = input.language.toLowerCase();
    if (!LANGUAGE_REGEX.test(language)) {
      throw new ValidationError(
        'Language must be a 2-letter ISO 639-1 code',
        { language: ['must be 2 lowercase letters'] },
        { language: input.language },
        'INVALID_LANGUAGE',
      );
    }
    return { ...input, body, language };
  }

  /** Wrap a persisted row in a `Review` instance. DB rows are by
   *  construction already valid; no re-validation runs here. */
  static fromPersistence(row: ReviewPersistenceRow): Review {
    return new Review(row);
  }
}

src/modules/social/domain/trip-comment.e.source:
/**
 * `TripComment` domain entity. A comment on a published trip (Phase 5
 * J4). Flat (no threading) in v1.
 *
 * DDD refactor by [G4.1]: the body validation (T1 non-empty +
 * T2 ≤ MAX_COMMENT_LENGTH after trim) moved off
 * `CreateCommentUseCase` and onto `TripComment.create()`. The
 * commentability gate (trip must be published) + block gate stay in
 * the use-case because they need repository access — the entity owns
 * data invariants only.
 *
 * Installed by prompt [J4]; entity-ized by [G4.1].
 */
import { ValidationError } from '@app/errors';

/** Max comment length — long enough for a real remark, short enough
 *  that the thread stays a thread (not a forum of essays). Exported
 *  for error-message formatting elsewhere. */
export const MAX_COMMENT_LENGTH = 1000;

/** Input shape for `TripComment.create()` — the new-comment payload
 *  BEFORE the DB assigns id + timestamps. */
export interface CreateTripCommentInput {
  readonly tripId: string;
  readonly authorId: string;
  readonly body: string;
}

/** Row shape returned by the Prisma adapter — id + timestamps filled
 *  in by the DB. */
export interface TripCommentPersistenceRow {
  readonly id: string;
  readonly tripId: string;
  readonly authorId: string;
  readonly body: string;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class TripComment {
  readonly id: string;
  readonly tripId: string;
  readonly authorId: string;
  readonly body: string;
  readonly createdAt: Date;
  readonly updatedAt: Date;

  private constructor(row: TripCommentPersistenceRow) {
    this.id = row.id;
    this.tripId = row.tripId;
    this.authorId = row.authorId;
    this.body = row.body;
    this.createdAt = row.createdAt;
    this.updatedAt = row.updatedAt;
  }

  /**
   * Validate + return a normalized CreateTripCommentInput ready for
   * `CommentRepository.create()`. Throws `ValidationError` on any
   * invariant break.
   *
   *   T1 body trims to non-empty
   *   T2 trimmed body ≤ MAX_COMMENT_LENGTH
   */
  static create(input: CreateTripCommentInput): CreateTripCommentInput {
    const body = input.body.trim();
    if (body.length === 0) {
      throw new ValidationError(
        'Comment cannot be empty',
        { body: ['must be non-empty'] },
        {},
        'INVALID_COMMENT_BODY',
      );
    }
    if (body.length > MAX_COMMENT_LENGTH) {
      throw new ValidationError(
        'Comment too long',
        { body: [`must be ≤ ${MAX_COMMENT_LENGTH} chars (got ${body.length})`] },
        { length: body.length },
        'INVALID_COMMENT_BODY',
      );
    }
    return { ...input, body };
  }

  /** Wrap a persisted row in a `TripComment` instance. */
  static fromPersistence(row: TripCommentPersistenceRow): TripComment {
    return new TripComment(row);
  }
}

/** A comment joined to its author's display name, for the thread UI.
 *  Composition (not `extends TripComment`) since `TripComment` is now
 *  a class with a private constructor — interfaces can't structurally
 *  extend classes that way without breaking the `instanceof` contract. */
export interface TripCommentWithAuthor {
  readonly id: string;
  readonly tripId: string;
  readonly authorId: string;
  readonly body: string;
  readonly createdAt: Date;
  readonly updatedAt: Date;
  readonly authorDisplayName: string;
}

src/modules/social/domain/vote.entity.ts.source:
/**
 * `Vote` domain entity. Generic ±1/0 vote — `targetType` + `targetId`
 * lets a single table serve itinerary items today and places /
 * restaurants / stays in follow-up slices without a schema change.
 *
 * DDD refactor by [G4.1]: `value` and `targetType` used to be guarded
 * only by the controller DTO + TypeScript narrowing. The entity now
 * also runtime-checks the discriminants on `Vote.create()` so adapter-
 * level upserts can't accept a malformed value via a raw call.
 *
 *   V1 value ∈ {-1, 0, +1}
 *   V2 targetType ∈ {itinerary_item, place, restaurant}
 *   V3 tripId, userId, targetId are non-empty strings
 *
 * `value` is -1 / 0 / +1 (thumbs-down / meh / thumbs-up). The
 * `0` row exists so a user can revoke a prior vote without
 * deleting the row — though v1's API uses DELETE for revoke,
 * so `0` is dormant today.
 *
 * Installed by prompt [IV.18.12.3]; entity-ized by [G4.1].
 */
import { ValidationError } from '@app/errors';

export type VoteTargetType = 'itinerary_item' | 'place' | 'restaurant';
export const VOTE_TARGET_TYPES: readonly VoteTargetType[] = [
  'itinerary_item',
  'place',
  'restaurant',
];

export type VoteValue = -1 | 0 | 1;
export const VOTE_VALUES: readonly VoteValue[] = [-1, 0, 1];

/** Input shape for `Vote.create()` — the upsert payload BEFORE the
 *  DB assigns id + timestamps. */
export interface CreateVoteInput {
  readonly tripId: string;
  readonly userId: string;
  readonly targetType: VoteTargetType;
  readonly targetId: string;
  readonly value: VoteValue;
}

/** Row shape returned by the Prisma adapter. */
export interface VotePersistenceRow {
  readonly id: string;
  readonly tripId: string;
  readonly userId: string;
  readonly targetType: VoteTargetType;
  readonly targetId: string;
  readonly value: VoteValue;
  readonly createdAt: Date;
}

export class Vote {
  readonly id: string;
  readonly tripId: string;
  readonly userId: string;
  readonly targetType: VoteTargetType;
  readonly targetId: string;
  readonly value: VoteValue;
  readonly createdAt: Date;

  private constructor(row: VotePersistenceRow) {
    this.id = row.id;
    this.tripId = row.tripId;
    this.userId = row.userId;
    this.targetType = row.targetType;
    this.targetId = row.targetId;
    this.value = row.value;
    this.createdAt = row.createdAt;
  }

  /**
   * Validate + return the CreateVoteInput ready for
   * `VoteRepository.upsert()`. Throws `ValidationError` on any
   * invariant break (V1/V2/V3).
   */
  static create(input: CreateVoteInput): CreateVoteInput {
    if (typeof input.tripId !== 'string' || input.tripId.length === 0) {
      throw new ValidationError(
        'tripId must be a non-empty string',
        { tripId: ['must be non-empty'] },
        {},
        'INVALID_VOTE_TARGET',
      );
    }
    if (typeof input.userId !== 'string' || input.userId.length === 0) {
      throw new ValidationError(
        'userId must be a non-empty string',
        { userId: ['must be non-empty'] },
        {},
        'INVALID_VOTE_TARGET',
      );
    }
    if (typeof input.targetId !== 'string' || input.targetId.length === 0) {
      throw new ValidationError(
        'targetId must be a non-empty string',
        { targetId: ['must be non-empty'] },
        {},
        'INVALID_VOTE_TARGET',
      );
    }
    if (!VOTE_TARGET_TYPES.includes(input.targetType)) {
      throw new ValidationError(
        `targetType must be one of ${VOTE_TARGET_TYPES.join(' | ')}`,
        { targetType: [`unknown: ${input.targetType}`] },
        { targetType: input.targetType },
        'INVALID_VOTE_TARGET',
      );
    }
    if (!VOTE_VALUES.includes(input.value)) {
      throw new ValidationError(
        'value must be -1, 0, or +1',
        { value: [`unknown: ${input.value}`] },
        { value: input.value },
        'INVALID_VOTE_VALUE',
      );
    }
    return input;
  }

  /** Wrap a persisted row in a `Vote` instance. */
  static fromPersistence(row: VotePersistenceRow): Vote {
    return new Vote(row);
  }
}

/**
 * Aggregate count of vote values for a single target — what the
 * `GET /trips/:tripId/votes` response renders. No per-user
 * breakdown by default (privacy + response-size); the authed
 * caller's own vote is surfaced separately as `mine`.
 */
export interface VoteTally {
  readonly targetType: VoteTargetType;
  readonly targetId: string;
  readonly up: number;
  readonly meh: number;
  readonly down: number;
  /** Sum: (+1×up) + (0×meh) + (-1×down). Convenient rank signal. */
  readonly score: number;
  /** The authed caller's own vote on this target, or `null`. */
  readonly mine: VoteValue | null;
}

